{
 "app_name": "gmail",
 "api_name": "forward_email_from_thread",
 "path": "/gmail/email_threads/{email_thread_id}/emails/{email_id}/forward",
 "method": "POST",
 "description": "Forward an email from an email thread to one or more recipients.",
 "parameters": [
  {
   "name": "email_thread_id",
   "type": "integer",
   "required": true,
   "description": "The ID of the email thread to forward.",
   "default": null,
   "constraints": []
  },
  {
   "name": "email_id",
   "type": "integer",
   "required": true,
   "description": "The ID of the email to forward.",
   "default": null,
   "constraints": []
  },
  {
   "name": "email_addresses",
   "type": "list[string]",
   "required": true,
   "description": "List of recipient email addresses.",
   "default": null,
   "constraints": []
  },
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from gmail app login.",
   "default": null,
   "constraints": []
  },
  {
   "name": "draft_not_send",
   "type": "boolean",
   "required": false,
   "description": "If true, the email will be saved as a draft instead of being sent. This way it can be edited before sending.",
   "default": false,
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": {
   "message": "string",
   "sent_email_thread_id": 1,
   "sent_email_id": 1,
   "draft_id": 1
  },
  "failure": {
   "message": "string"
  }
 }
}

